function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const profile = input.profile === 'runtime' ? 'runtime' : 'demo'
  const body = {
    name: String(input.name || '').trim(),
    source: input.source,
    direction: input.direction || 'long',
    winsorize: input.winsorize ?? 0.01,
    neutralize: input.neutralize || [],
    start_date: String(input.start_date || '').trim(),
    end_date: String(input.end_date || '').trim(),
    frequency: input.frequency || 'monthly',
    quantiles: input.quantiles || 5,
    profile,
  }
  if (input.expression) body.expression = String(input.expression)
  if (input.symbols) body.symbols = input.symbols.map(String)
  if (input.min_price !== undefined) body.min_price = input.min_price
  if (input.min_history_days !== undefined) body.min_history_days = input.min_history_days
  if (input.min_average_amount !== undefined) body.min_average_amount = input.min_average_amount
  const response = await fetch(apiOrigin() + '/api/factor-research/evaluate', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
